function validate([row, col, cells]) {
  if (!Number.isInteger(row) || !Number.isInteger(col) || row < 2 || col < 2) return 'row and col must be integers of at least 2.';
  if (row * col < 4 || row * col > 20000) return 'row * col must be between 4 and 20000.';
  if (!Array.isArray(cells) || cells.length !== row * col) return 'cells must list every cell exactly once (row * col pairs).';
  const seen = new Set();
  for (const cell of cells) {
    if (!Array.isArray(cell) || cell.length !== 2) return 'Each cell is a pair [r, c].';
    const [r, c] = cell;
    if (!Number.isInteger(r) || !Number.isInteger(c) || r < 1 || r > row || c < 1 || c > col) return 'Each cell must lie inside the grid (1-based).';
    if (seen.has(r * (col + 1) + c)) return 'Cells must not repeat.';
    seen.add(r * (col + 1) + c);
  }
  return null;
}

