function latestDayToCross(row, col, cells) {
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const canCross = (day) => {
    const blocked = Array.from({ length: row }, () => new Array(col).fill(false));
    for (let i = 0; i < day; i++) {
      blocked[cells[i][0] - 1][cells[i][1] - 1] = true;
    }
    const queue = [];
    for (let c = 0; c < col; c++) {
      if (!blocked[0][c]) {
        blocked[0][c] = true;
        queue.push([0, c]);
      }
    }
    for (let head = 0; head < queue.length; head++) {
      const [r, c] = queue[head];
      if (r === row - 1) {
        return true;
      }
      for (const [dr, dc] of directions) {
        const nr = r + dr;
        const nc = c + dc;
        if (nr >= 0 && nr < row && nc >= 0 && nc < col && !blocked[nr][nc]) {
          blocked[nr][nc] = true;
          queue.push([nr, nc]);
        }
      }
    }
    return false;
  };
  let left = 0;
  let right = cells.length;
  while (left < right) {
    const mid = left + Math.floor((right - left + 1) / 2);
    if (canCross(mid)) {
      left = mid;
    } else {
      right = mid - 1;
    }
  }
  return left;
}

