function latestDayToCross(row, col, cells) {
  const grid = Array.from({ length: row }, () => new Array(col).fill('.'));
  const reachesBottom = () => {
    const seen = new Set();
    const visit = (r, c) => {
      if (r < 0 || r >= row || c < 0 || c >= col || grid[r][c] === '#' || seen.has(r * col + c)) return false;
      seen.add(r * col + c);
      if (r === row - 1) return true;
      return visit(r + 1, c) || visit(r - 1, c) || visit(r, c + 1) || visit(r, c - 1);
    };
    for (let c = 0; c < col; c++) if (visit(0, c)) return true;
    return false;
  };
  let last = 0;
  for (let day = 1; day <= cells.length; day++) {
    grid[cells[day - 1][0] - 1][cells[day - 1][1] - 1] = '#';
    if (reachesBottom()) last = day;
  }
  return last;
}

