function generate(rand, size) {
  let row, col;
  if (size === 'small') {
    do {
      row = 2 + Math.floor(rand() * 4);
      col = 2 + Math.floor(rand() * 4);
    } while (row * col < 4);
  } else {
    const shapes = [[40, 50], [2, 1000], [1000, 2], [20, 100], [100, 20], [44, 45]];
    [row, col] = shapes[Math.floor(rand() * shapes.length)];
  }
  const cells = [];
  for (let r = 1; r <= row; r++) for (let c = 1; c <= col; c++) cells.push([r, c]);
  for (let i = cells.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [cells[i], cells[j]] = [cells[j], cells[i]];
  }
  // Sometimes flood one row early, so the answer is pinned near the front.
  if (rand() < 0.25) {
    const target = 1 + Math.floor(rand() * row);
    const early = cells.filter(([r]) => r === target);
    const rest = cells.filter(([r]) => r !== target);
    const cut = Math.floor(rand() * rest.length / 2);
    return [row, col, [...rest.slice(0, cut), ...early, ...rest.slice(cut)]];
  }
  return [row, col, cells];
}
